    "script": "女の人が話しています。この女の人は何が好きですか。\n女：はじめまして。山田真理子です。北海道から来ました。好きなことは走ったりプールで泳いだりすることです。歌を歌ったりギターを弾いたりすることも好きです。嫌いなことは料理をすることです。よろしくお願いします。",
