    "type": "listening-text-only",
    "script": "時計屋で、女の人と店の人が話しています。女の人はいつ時計を取りに来ますか。\n女：すみません。この時計壊れてしまったんですが、直りますか。\n男：ああ、これなら直りますよ。四五日かかりますが。えーと、今週の土曜日にはできます。\n女：土曜日ですか。あのう、金曜日に使いたいんですが。\n男：じゃあ、木曜日でいいですか。\n女：木曜日は取りに来られないんですが。\n男：ううん、すこし値段が高くなりますけど、水曜日の夕方なら。\n女：何時頃ですか。\n男：ううん、五時頃ですね。\n女：ああ、じゃ、それでお願いします。\n女の人はいつ時計を取りに来ますか。",
