    "type": "listening-text-only",
    "script": "体育館で、男の先生が話しています。その後、女の学生が質問します。この女の学生は何色の帽子をかぶりますか。\n男：ええと、今日はバスケットボールをします。四つのグループになって練習します。第一グループの人は赤の帽子をかぶってください。第二グループの人は黄色、第三の人は青、第四の人は緑の帽子です。\n女：あのう、先生。私、どのグループか分らないんですけど。\n男：ちょっと待ってください。ええと、第四ですよ。\n女：分かりました。じゃ、緑ですね。\n男：あっ、でも、今日は第二グループに休みのひとが多いなあ。悪いけど、このグループに入ってもらえますか。\n女：はい、分かりました。\nこの女の学生は何色の帽子をかぶりますか。",
    "audioUrl": null,
