    "type": "listening-text-only",
    "script": "バスの中で、旅行会社の人が話しています。バスのお客さんは何時までにバスに戻らなければなりませんか。\n女：皆様、西山公園に着きました。今、予定より少し遅れまして、1時25分です。ここでバスを降りて、一時間半ぐらい自由時間があります。西山公園はとても広い公園で、1200年前に建てられた寺や神社が残っています。ぜひ行ってみてください。3時には出発しますから、5分前までに必ずバスに戻ってください。\nバスの中のお客さんは何時までにバスに戻らなければなりませんか。",
