    "script": "女の人が公園の掃除について話しています。男の人は何をしなければなりませんか。\n女：皆さん、今日は公園の掃除に来てくれて、ありがとうございます。では、まず、小学生のお子さんたちは公園に落ちている紙のゴミを拾って、袋に入れてください。それから、ええと、男の人は空き缶や瓶を拾ってもらえますか。缶と瓶は一緒の袋に入れてください。最後に、女の人ですが、私たちは木の周りに落ちている葉っぱを掃除しましょう。それでは、始めましょう。\n男の人は何をしなければなりませんか。",
