    "script": "女の人と男の人が話しています。二人はどこで会いますか？\n女：来月のパーティーの知らせ、見た？\n男：うん、桜ホテルだね。一緒に行こうよ。\n女：いいよ、どこで会う？ホテルの入り口にする？\n男：僕は場所がよく分からないから、駅の出口でもいい？\n女：駅は人が多いから、駅前の喫茶店はどう？\n男：わかった。\n二人はどこで会いますか？",
