    "script": "女の人が生まれた町について話しています。女の人はいつ行くのが一番いいといっていますか。\n女：私の生まれた町は山川町です。日本の北のほうにある町です。冬が長いので、春になると、いろいろなお祭りをします。その中でも歴史祭りが一番有名です。夏は雨が降らなくて気持ちがいいです。秋にはいろいろな果物が食べられます。どの季節もいいですが、歴史祭りの時が一番面白いです。ぜひ、歴史祭りのときに来てください。\n女の人はいつ行くのが一番いいといっていますか。",
